import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static class Matrix extends ArrayList<ArrayList<Integer>> {
        public Matrix(int rows, int cols) {
            super();
            for (int i = 0; i < rows; i++) {
                ArrayList<Integer> row = new ArrayList<>();
                for (int j = 0; j < cols; j++) {
                    row.add(0);
                }
                this.add(row);
            }
        }

        public Matrix clone() {
            Matrix copy = new Matrix(this.size(), this.get(0).size());
            for (int i = 0; i < this.size(); i++) {
                for (int j = 0; j < this.get(0).size(); j++) {
                    copy.get(i).set(j, this.get(i).get(j));
                }
            }
            return copy;
        }
    }

    static List<Matrix> dp = new ArrayList<>();
    static Matrix baseMatrix;
    static Matrix tmp;

    static Matrix shift(final Matrix mat, int s) {
        int size = mat.size() - 1;
        s = (size - s) % size;
        Matrix res = new Matrix(mat.size(), mat.get(0).size());
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                res.get(i).set(j, mat.get((i + s) % size).get((j + s) % size));
            }
        }
        for (int j = 0; j < size; ++j) {
            res.get(size).set(j, mat.get(size).get((j + s) % size));
        }
        return res;
    }

    static Matrix multiply(final Matrix a, final Matrix b) {
        int n = a.size();
        int k = a.get(0).size();
        int m = b.get(0).size();

        Matrix res = new Matrix(n, m);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                long sum = 0;
                for (int l = 0; l < k; ++l) {
                    sum += (long) a.get(i).get(l) * b.get(l).get(j);
                }
                res.get(i).set(j, (int) (sum % MOD));
            }
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        int max_depth = 0;
        long tmp_n = n;
        while (tmp_n != 0) {
            ++max_depth;
            tmp_n /= k;
        }

        // Initialize dp
        for (int d = 0; d < max_depth; d++) {
            if (d == 0) {
                Matrix first = new Matrix(k + 1, k + 1);
                for (int i = 0; i <= k; i++) {
                    for (int j = 0; j <= k; j++) {
                        if (i == j || j == 0) {
                            first.get(i).set(j, 1);
                        } else {
                            first.get(i).set(j, 0);
                        }
                    }
                }
                dp.add(first);
            } else {
                Matrix identity = new Matrix(k + 1, k + 1);
                for (int i = 0; i <= k; i++) {
                    for (int j = 0; j <= k; j++) {
                        if (i == j) {
                            identity.get(i).set(j, 1);
                        } else {
                            identity.get(i).set(j, 0);
                        }
                    }
                }
                Matrix prev = dp.get(d - 1);
                Matrix current = identity.clone();
                int current_x = k;
                for (int i = 0; (1 << i) <= current_x; i++) {
                    if ((current_x & (1 << i)) != 0) {
                        current = multiply(prev, shift(current, 1 << i));
                        current_x ^= (1 << i);
                    }
                    prev = multiply(prev, shift(prev, 1 << i));
                }
                dp.add(current);
            }
        }

        baseMatrix = new Matrix(1, k + 1);
        baseMatrix.get(0).set(k, 1);

        long x = n;
        List<Integer> digits = new ArrayList<>();
        while (x != 0) {
            digits.add((int) (x % k));
            x /= k;
        }

        int shift_idx = 0;
        for (int idx = digits.size() - 1; idx >= 0; --idx) {
            int rem = digits.get(idx);
            for (int it = 0; it < rem; ++it, shift_idx = (shift_idx + 1) % k) {
                baseMatrix = multiply(baseMatrix, shift(dp.get(idx), shift_idx));
            }
        }

        int total_res = 0;
        for (int i = 0; i <= k; ++i) {
            total_res = (total_res + baseMatrix.get(0).get(i)) % (int) MOD;
        }

        System.out.println(total_res);
        sc.close();
    }
}
